{
  "title": "夜探恶人谷",
  "scene": "你已潜入恶人谷，四周静悄悄的，偶尔传来远处的狼嚎。你的目标是寻找失踪的同门。谷中有一座古旧的客栈，门半开，依稀可见里面灯火通明。客栈左边有一座小木桥通往一片密林，密林深处似乎有些许光亮。右边则是一座高大的石墙，墙上刻着一些奇怪的文字，隐约能辨认出“凡入谷者，不得轻功”几个字。空气中弥漫着一股神秘的气息，让人不禁怀疑这里是否藏有不为人知的秘密。",
  "goal": "找到并安全带回失踪同门",
  "clue": "石墙上的文字和密林深处的光亮",
  "choices": [
    {
      "id": "A",
      "text": "直接进入客栈",
      "outcome": "你推开门，发现客栈内空无一人。突然，四周的暗处涌出无数恶人，你寡不敌众，被制住。原来客栈是他们的陷阱，失踪的同门并未在此。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "用轻功跃过石墙",
      "outcome": "你施展轻功跃过石墙，却感到一阵剧痛，身体重重地摔在地上。石墙上的文字并非虚言，这里布满了机关，轻功反而触发了机关。你受伤不轻，但幸运地逃了出来。",
      "result": "fail",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "过桥进入密林",
      "outcome": "你小心翼翼地走过木桥，进入密林深处。光亮来自一个隐蔽的山洞，洞内正是失踪的同门。他告诉你，这里有一条秘密通道可以安全离开恶人谷。你成功带他返回，并发现了一块刻有门派秘密的石碑。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
